--
-- Table structure for table `fatura`
--

DROP TABLE IF EXISTS `fatura`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fatura` (
  `id_fatura` int(11) NOT NULL AUTO_INCREMENT,
  `id_unidade_consumo` int(11) NOT NULL,
  `id_tarifa` int(11) NOT NULL,
  `mes_referencia` date NOT NULL,
  `total_kwh` decimal(10,2) NOT NULL,
  `valor_total` decimal(10,2) NOT NULL,
  `data_emissao` date NOT NULL,
  `data_vencimento` date DEFAULT NULL,
  `status_pagamento` varchar(10) NOT NULL DEFAULT 'ABERTA',
  PRIMARY KEY (`id_fatura`),
  UNIQUE KEY `id_unidade_consumo` (`id_unidade_consumo`,`mes_referencia`),
  KEY `id_tarifa` (`id_tarifa`),
  CONSTRAINT `fatura_ibfk_1` FOREIGN KEY (`id_unidade_consumo`) REFERENCES `unidade_consumo` (`id_unidade_consumo`),
  CONSTRAINT `fatura_ibfk_2` FOREIGN KEY (`id_tarifa`) REFERENCES `tarifa` (`id_tarifa`),
  CONSTRAINT `ck_fatura_status` CHECK (`status_pagamento` in ('ABERTA','PAGA','ATRASADA')),
  CONSTRAINT `ck_fatura_valores` CHECK (`valor_total` >= 0 and `total_kwh` >= 0)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

